function nearby_positions(
        position::Int,
        model::ABM{<:GraphSpace};
        neighbor_type::Symbol = :default,
    )
    @assert neighbor_type ∈ (:default, :all, :in, :out)
    return if neighbor_type == :default
        Graphs.neighbors(abmspace(model).graph, position)
    elseif neighbor_type == :in
        Graphs.inneighbors(abmspace(model).graph, position)
    elseif neighbor_type == :out
        Graphs.outneighbors(abmspace(model).graph, position)
    else
        Graphs.all_neighbors(abmspace(model).graph, position)
    end

/// ### Graph Indices
///
/// The graph maintains indices for nodes and edges, and node and edge
/// weights may be accessed mutably. Indices range in a compact interval, for
/// example for *n* nodes indices are 0 to *n* - 1 inclusive.
///
/// `NodeIndex` and `EdgeIndex` are types that act as references to nodes and edges,
/// but these are only stable across certain operations:
///
/// * **Removing nodes or edges may shift other indices.** Removing a node will force the last node
///   to shift its index to take its place. Similarly, removing an edge shifts the index of the last
///   edge.
/// * Adding nodes or edges keeps indices stable.
///
/// The `Ix` parameter is `u32` by default. The goal is that you can ignore this parameter
/// completely unless you need a very big graph -- then you can use `usize`.
///
/// * The fact that the node and edge indices in the graph each are numbered in compact intervals
///   (from 0 to *n* - 1 for *n* nodes) simplifies some graph algorithms.
///
/// * You can select graph index integer type after the size of the graph. A smaller size may have
///   better performance.
///
/// * Using indices allows mutation while traversing the graph, see `Dfs`, and
///   `.neighbors(a).detach()`.
///
/// * You can create several graphs using the equal node indices but with differing weights or
///   differing edges.
///
/// * Indices don't allow as much compile time checking as references.

/// Try to add an edge from a to b to the graph, with its associated
/// data weight.
///
/// Return the index of the new edge.
///
/// Computes in O(1) time.
///
/// Possible errors:
/// - [`GraphError::NodeOutBounds`] - if any of the nodes don't exist.<br>
/// - [`GraphError::EdgeIxLimit`] if the `Graph` is at the maximum number of edges for its index
///   type (N/A if usize).
///
/// Note: Graph allows adding parallel (“duplicate”) edges. If you want
/// to avoid this, use [.update_edge(a, b, weight)](#method.update_edge) instead.
pub fn try_add_edge(
    &mut self,
    a: NodeIndex<Ix>,
    b: NodeIndex<Ix>,
    weight: E,
) -> Result<EdgeIndex<Ix>, GraphError> {
    let edge_idx = EdgeIndex::new(self.edges.len());
    if !(<Ix as IndexType>::max().index() == !0 || EdgeIndex::end() != edge_idx) {
        return Err(GraphError::EdgeIxLimit);
    }

    let mut edge = Edge {
        weight,
        node: [a, b],
        next: [EdgeIndex::end(); 2],
    };
    match index_twice(&mut self.nodes, a.index(), b.index()) {
        Pair::None => return Err(GraphError::NodeOutBounds),
        Pair::One(an) => {
            edge.next = an.next;
            an.next[0] = edge_idx;
            an.next[1] = edge_idx;
        }
        Pair::Both(an, bn) => {
            // a and b are different indices
            edge.next = [an.next[0], bn.next[1]];
            an.next[0] = edge_idx;
            bn.next[1] = edge_idx;
        }
    }
    self.edges.push(edge);
    Ok(edge_idx)

/// `StableGraph<N, E, Ty, Ix>` is a graph datastructure using an adjacency
/// list representation.
///
/// The graph **does not invalidate** any unrelated node or edge indices when
/// items are removed.
///
/// `StableGraph` is parameterized over:
///
/// - Associated data `N` for nodes and `E` for edges, also called *weights*. The associated data
///   can be of arbitrary type.
/// - Edge type `Ty` that determines whether the graph edges are directed or undirected.
/// - Index type `Ix`, which determines the maximum size of the graph.
///
/// The graph uses **O(|V| + |E|)** space where V is the set of nodes and E is the
/// set of edges, and allows fast node and edge insert and efficient graph search.
///
/// It implements **O(e')** edge lookup and edge and node removals, where **e'**
/// is some local measure of edge count.
///
/// - Nodes and edges are each numbered in an interval from *0* to some number *m*, but *not all*
///   indices in the range are valid, since gaps are formed by deletions.
///
/// - You can select graph index integer type after the size of the graph. A smaller size may have
///   better performance.
///
/// - Using indices allows mutation while traversing the graph, see `Dfs`.
///
/// - The `StableGraph` is a regular rust collection and is `Send` and `Sync` (as long as associated
///   data `N` and `E` are).
///
/// - Indices don't allow as much compile time checking as references.
///
/// Depends on crate feature `stable_graph` (default). *Stable Graph is still
/// missing a few methods compared to Graph. You can contribute to help it
/// achieve parity.*
pub struct StableGraph<N, E, Ty = Directed, Ix = DefaultIx> {
    g: Graph<Option<N>, Option<E>, Ty, Ix>,
    node_count: usize,
    edge_count: usize,

    // node and edge free lists (both work the same way)
    //
    // free_node, if not NodeIndex::end(), points to a node index
    // that is vacant (after a deletion).
    // The free nodes form a doubly linked list using the fields Node.next[0]
    // for forward references and Node.next[1] for backwards ones.
    // The nodes are stored as EdgeIndex, and the _into_edge()/_into_node()
    // methods convert.
    // free_edge, if not EdgeIndex::end(), points to a free edge.
    // The edges only form a singly linked list using Edge.next[0] to store
    // the forward reference.
    free_node: NodeIndex<Ix>,
    free_edge: EdgeIndex<Ix>,

/// Add a node (also called vertex) with associated data `weight` to the graph.
///
/// Computes in **O(1)** time.
///
/// Return the index of the new node.
///
/// **Panics** if the `StableGraph` is at the maximum number of nodes for
/// its index type.
#[track_caller]
pub fn add_node(&mut self, weight: N) -> NodeIndex<Ix> {
    self.try_add_node(weight).unwrap()
}

/// Add a node (also called vertex) with associated data `weight` to the graph.
///
/// Computes in **O(1)** time.
///
/// Return the index of the new node.
///
/// Return [`GraphError::NodeIxLimit`] if the `StableGraph` is at the maximum number of nodes
/// for its index.
pub fn try_add_node(&mut self, weight: N) -> Result<NodeIndex<Ix>, GraphError> {
    if self.free_node != NodeIndex::end() {
        let node_idx = self.free_node;
        self.occupy_vacant_node(node_idx, weight);
        Ok(node_idx)
    } else {
        self.node_count += 1;
        self.g.try_add_node(Some(weight))
    }

